{
  "root_cause": "The datepicker (via Vanilla Calendar Pro) calls preventDefault() on the Tab keydown event when the calendar popup is open, blocking the browser's default focus traversal to the next form field. The keydown event fires on the departure input (target #departure) with defaultPrevented=true, preventing focus from moving to the passengers field.",
  "repair_strategy": "Add a capturing-phase keydown listener on the datepicker input that detects Tab key when the calendar is shown. The listener calls hide() to close the calendar but does NOT call preventDefault(), allowing the Tab event to continue its default behavior (moving focus to the next focusable element). The listener is added with {capture: true} to run before VCP's listener, and cleaned up in dispose().",
  "edits": [
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "  protected declare _onOutside: (event: Event) => void
  protected declare _onTriggerClick: () => void

  constructor(element?: string | Element | null, config?: Partial<DatepickerConfig> | null) {
    super(element, config)

    this._calendar = null
    this._isShown = false

    this._initCalendar()
  }",
      "after": "  protected declare _onOutside: (event: Event) => void
  protected declare _onTriggerClick: () => void
  protected declare _onKeyDown: (event: KeyboardEvent) => void

  constructor(element?: string | Element | null, config?: Partial<DatepickerConfig> | null) {
    super(element, config)

    this._calendar = null
    this._isShown = false
    this._onKeyDown = null

    this._initCalendar()
  }"
    },
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "    this._setupDismiss()

    // Set initial value if input has a value
    if (this._isInput && this._element.value) {
      this._parseInputValue()
    }

    // Populate input/display with preselected dates
    this._updateDisplayWithSelectedDates()
  }",
      "after": "    this._setupDismiss()

    // Add keydown listener for Tab to hide the datepicker and allow focus to change
    if (this._isInput) {
      this._onKeyDown = (event: KeyboardEvent) => {
        if (event.key === 'Tab' && this._isShown) {
          this.hide()
        }
      }
      this._element.addEventListener('keydown', this._onKeyDown, { capture: true })
    }

    // Set initial value if input has a value
    if (this._isInput && this._element.value) {
      this._parseInputValue()
    }

    // Populate input/display with preselected dates
    this._updateDisplayWithSelectedDates()
  }"
    },
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "  override dispose(): void {
    if (this._themeObserver) {
      this._themeObserver.disconnect()
      this._themeObserver = null
    }

    if (this._onOutside) {
      EventHandler.off(document, EVENT_FOCUSIN, this._onOutside)
      EventHandler.off(document, EVENT_POINTERDOWN, this._onOutside)
    }

    if (this._onTriggerClick) {
      EventHandler.off(this._positionElement, EVENT_CLICK, this._onTriggerClick)
    }

    if (this._calendar) {
      this._calendar.destroy()
    }

    this._calendar = null
    super.dispose()
  }",
      "after": "  override dispose(): void {
    if (this._themeObserver) {
      this._themeObserver.disconnect()
      this._themeObserver = null
    }

    if (this._onOutside) {
      EventHandler.off(document, EVENT_FOCUSIN, this._onOutside)
      EventHandler.off(document, EVENT_POINTERDOWN, this._onOutside)
    }

    if (this._onTriggerClick) {
      EventHandler.off(this._positionElement, EVENT_CLICK, this._onTriggerClick)
    }

    // Remove our keydown listener if we added one
    if (this._isInput && this._onKeyDown) {
      this._element.removeEventListener('keydown', this._onKeyDown, { capture: true })
      this._onKeyDown = null
    }

    if (this._calendar) {
      this._calendar.destroy()
    }

    this._calendar = null
    super.dispose()
  }"
    }
  ],
  "expected_accessibility_effect": "Pressing Tab from the departure date field will move focus to the passengers field, restoring expected form navigation behavior for keyboard users. The datepicker will close automatically when Tab is pressed while open.",
  "functional_risks": [
    "Hiding the datepicker on Tab might interfere with users who expect to use Tab to navigate within the calendar (though the current behavior prevents Tab entirely, this change prioritizes form navigation over potential calendar-internal Tab navigation).",
    "If the datepicker's hide method is asynchronous, the calendar might briefly remain visible after focus has moved to the next field, though this is unlikely as hide() is synchronous in the current implementation."
  ],
  "verification_requirements": [
    "Verify that pressing Tab from the departure date field moves focus to the passengers field.",
    "Verify that the datepicker is hidden when focus leaves the departure field via Tab.",
    "Verify that other datepicker keyboard interactions (Escape to close, arrow keys to navigate dates, Enter to select) still function correctly.",
    "Verify that the datepicker still opens correctly on focus and click, and that inline datepickers are unaffected."
  ]
}
